-- ----------------------------
-- Procedure structure for AssignBondID
-- ----------------------------
DROP PROCEDURE IF EXISTS `AssignBondID`;
delimiter ;;
CREATE PROCEDURE `AssignBondID`(IN `input_id` INT)
BEGIN
    DECLARE loan_types INT;
    DECLARE latest_bond_id VARCHAR(20);
    DECLARE new_bond_id VARCHAR(20);
    DECLARE number_part INT;
    DECLARE prefix VARCHAR(2);
    DECLARE year_part VARCHAR(4);
    DECLARE formatted_number VARCHAR(5);
    
    SET year_part = CAST(YEAR(CURDATE()) AS CHAR);
    
    SELECT l.loan_type INTO loan_types from loans l WHERE l.id = input_id;
    
    IF loan_types = 0 THEN
        SET prefix = 'PB';
    ELSEIF loan_types = 1 THEN
        SET prefix = 'CB';
    ELSE
        SET prefix = 'XX';
    END IF;
    
    SELECT lv.bond_id INTO latest_bond_id 
    FROM loan_voucher lv where lv.bond_id IS NOT NULL
    AND lv.loan_type = loan_types ORDER BY lv.id DESC LIMIT 1;
    
    IF latest_bond_id IS NULL THEN
        SET new_bond_id = CONCAT(prefix, year_part, '0001');
    ELSE
        SET number_part = CAST(SUBSTRING(latest_bond_id, 7) AS UNSIGNED);
        SET number_part = number_part + 1;
        SET formatted_number = LPAD(number_part, 4, '0');
        SET new_bond_id = CONCAT(prefix, year_part, formatted_number);
    END IF;
        
    UPDATE loan_voucher lv
    SET lv.bond_id = new_bond_id 
    WHERE lv.advice_id = input_id;
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for AssignRECID
-- ----------------------------
DROP PROCEDURE IF EXISTS `AssignRECID`;
delimiter ;;
CREATE PROCEDURE `AssignRECID`(IN `input_id` VARCHAR(20))
BEGIN
    DECLARE user varchar(7);
    DECLARE latest_bond_id VARCHAR(20);
    DECLARE new_bond_id VARCHAR(20);
    DECLARE number_part INT;
    DECLARE prefix VARCHAR(3);
    DECLARE year_part VARCHAR(4);
    DECLARE formatted_number VARCHAR(5);
    
    SET year_part = CAST(YEAR(CURDATE()) AS CHAR);
    
    SET prefix = 'REC';

    SELECT lv.r_id INTO latest_bond_id 
    FROM member_receipt lv where lv.r_id IS NOT NULL
    AND lv.r_id != input_id ORDER BY lv.id DESC LIMIT 1;
    
    SELECT lv.user_id INTO user FROM member_receipt lv WHERE lv.r_id = input_id LIMIT 1;
    
    IF latest_bond_id IS NULL THEN
        SET new_bond_id = CONCAT(prefix, year_part, '00001');
    ELSE
        SET number_part = CAST(SUBSTRING(latest_bond_id, 8, 5) AS UNSIGNED);
        SET number_part = number_part + 1;
        SET formatted_number = LPAD(number_part, 5, '0');
        SET new_bond_id = CONCAT(prefix, year_part, formatted_number);
    END IF;
        
    UPDATE member_receipt lv
    SET lv.r_id = new_bond_id 
    WHERE lv.r_id = input_id;
    
    UPDATE receipt l
    SET l.v_id = new_bond_id
    WHERE l.v_id = input_id;
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for AssignVOCID
-- ----------------------------
DROP PROCEDURE IF EXISTS `AssignVOCID`;
delimiter ;;
CREATE PROCEDURE `AssignVOCID`(IN `input_id` VARCHAR(20))
BEGIN
    DECLARE latest_bond_id VARCHAR(20);
    DECLARE new_bond_id VARCHAR(20);
    DECLARE number_part INT;
    DECLARE prefix VARCHAR(3);
    DECLARE year_part VARCHAR(4);
    DECLARE formatted_number VARCHAR(5);
    
    SET year_part = CAST(YEAR(CURDATE()) AS CHAR);
    
    SET prefix = 'VOC';

    SELECT lv.v_id INTO latest_bond_id 
    FROM member_voucher lv where lv.v_id IS NOT NULL
    AND lv.v_id != input_id ORDER BY lv.id DESC LIMIT 1;
    
    IF latest_bond_id IS NULL THEN
        SET new_bond_id = CONCAT(prefix, year_part, '00001');
    ELSE
        SET number_part = CAST(SUBSTRING(latest_bond_id, 8, 5) AS UNSIGNED);
        SET number_part = number_part + 1;
        SET formatted_number = LPAD(number_part, 5, '0');
        SET new_bond_id = CONCAT(prefix, year_part, formatted_number);
    END IF;
        
    UPDATE member_voucher lv
    SET lv.v_id = new_bond_id 
    WHERE lv.v_id = input_id;
    
    UPDATE voucher l
    SET l.v_id = new_bond_id
    WHERE l.v_id = input_id;
    
END
;;
delimiter ;

