SELECT  count(loan_approve_date) as noloan into loanno  FROM `loans`
where user_id = p_userId  and loan_type = '0' and loan_status = 3;

IF (loanno < 2 ) THEN
 SELECT  loan_balance,intrest_rate INTO openingloanbal,emirate  FROM `loans`
where user_id = p_userId  and loan_type = '0' and loan_status = 3 ;

 END IF;
 IF (loanno > 1 ) THEN 
SELECT MAX(loan_approve_date) AS second_max_loandate INTO loanSecondmaxDate
FROM loans
WHERE loan_approve_date < (SELECT MAX(loan_approve_date) FROM loans) 
and user_id = p_userId  and loan_type = '0' and loan_status = 3;

SELECT  loan_balance,intrest_rate INTO openingloanbal,emirate  FROM `loans`
where user_id = p_userId  and loan_type = '0' and loan_status = 3 and  DATE(loan_approve_date) = loanSecondmaxDate;

SELECT  DATE_FORMAT(MAX(loan_approve_date),'%d-%m-%Y') as max_loandate,month(date(MAX(loan_approve_date))) as max_loanmnth,year(date(MAX(loan_approve_date))) as max_loanmnyr into varcompany1,lnmonth,lnyear  FROM `loans`
 where user_id = p_userId  and loan_type = '0' and loan_status = 3;

SELECT  loan_balance into lnadv  FROM `loans`
 where user_id = p_userId  and loan_type = '0' and loan_status = 3 and  DATE_FORMAT(DATE(loan_approve_date),'%d-%m-%Y') = varcompany1;


END IF;

