SELECT amount INTO emiPLintaprl FROM `recovery_data`
 where user_id =p_userId
and YEAR(for_date) = fisrt_fiyear
 and (MONTH(for_date) =04 or MONTH(for_date) =4) and wage_type = '6025' order by for_date desc LIMIT 1;

SET  emiPLaprltot = openingloanbal - emiPLaprl;





IF(openingloanbal != 0) THEN
   set emiPLactintaprl = openingloanbal * emirate / 1200;
END IF;


SELECT amount INTO emiPLintmay FROM `recovery_data`
 where user_id =p_userId
and YEAR(for_date) = fisrt_fiyear
 and (MONTH(for_date) =05 or MONTH(for_date) =5) and wage_type = '6025' order by for_date desc LIMIT 1;


