set cashCLdepoctactint = cashCLdepoct * CLemirate / 1200;

SELECT IFNULL(sum(total_amount),0) INTO cashCLdepnov FROM `member_receipt` 
where  user_id = p_userId and YEAR(created_date) = fisrt_fiyear
and (MONTH(created_date) =11) and category = 'COMMODITY'
and paymenttype='3';

set cashCLdepnovactint = cashCLdepnov * CLemirate / 1200;

SELECT IFNULL(sum(total_amount),0) INTO cashCLdepdec FROM `member_receipt` 
where  user_id = p_userId and YEAR(created_date) = fisrt_fiyear
and (MONTH(created_date) =12) and category = 'COMMODITY'
and paymenttype='3';

set cashCLdepdecactint = cashCLdepdec * CLemirate / 1200;


SELECT IFNULL(sum(total_amount),0) INTO cashCLdepjan FROM `member_receipt` 
where  user_id = p_userId 
and YEAR(created_date) = second_fiyear
and (MONTH(created_date) =01 or MONTH(created_date) =1) and category = 'COMMODITY'
and paymenttype='3';

set cashCLdepjanactint = cashCLdepjan * CLemirate / 1200;

SELECT IFNULL(sum(total_amount),0) INTO cashCLdepfeb FROM `member_receipt` 
where  user_id = p_userId 
and YEAR(created_date) = second_fiyear
and (MONTH(created_date) =02 or MONTH(created_date) =2) and category = 'COMMODITY'
and paymenttype='3';

set cashCLdepfebactint = cashCLdepfeb * CLemirate / 1200;

SELECT IFNULL(sum(total_amount),0) INTO cashCLdepmarch FROM `member_receipt` 
where  user_id = p_userId 
and YEAR(created_date) = second_fiyear
and (MONTH(created_date) =03 or MONTH(created_date) =3) and category = 'COMMODITY'
and paymenttype='3';

IF (fisrt_fiyear = lastCloanded_cdyear) THEN
        IF(lastCloanded_cdmnth = 4) THEN
          SET  AVLoanClosebal = emiCLaprltot;
         END IF;
      IF(lastCloanded_cdmnth = 5) THEN
         SET  AVLoanClosebal = emiCLmaytot;
        
       END IF;
        IF(lastCloanded_cdmnth = 6) THEN
         SET  AVLoanClosebal = emiCLjunetot;
         
         END IF;
        IF(lastCloanded_cdmnth = 7) THEN
         SET  AVLoanClosebal = emiCLjulytot;
             
       END IF;
       IF(lastCloanded_cdmnth = 8) THEN
        SET  AVLoanClosebal = emiCLaugtot;
       
       END IF;
      IF(lastCloanded_cdmnth = 9) THEN
        SET  AVLoanClosebal = emiCLseptot;
       
