        SET  AVLoanClosebal = emiCLnovtot;
       
       END IF;
     IF(lastCloanded_cdmnth = 12) THEN
        SET  AVLoanClosebal = emiCLdectot;        

       END IF;
END IF;
IF (second_fiyear = lastCloanded_cdyear) THEN
   IF(lastCloanded_cdmnth = 1) THEN
        SET  AVLoanClosebal = emiCLjantot;
       
       END IF;
        IF(lastCloanded_cdmnth = 2) THEN
        SET  AVLoanClosebal = emiCLfebtot;       

       END IF;
       IF(lastCloanded_cdmnth = 3) THEN
        SET  AVLoanClosebal = emiCLmarchtot;
        
       END IF;
END IF;


set cashCLdepmarchactint = cashCLdepmarch * CLemirate / 1200;

set totalCLcashdep = cashCLdepaprl + cashCLdepmay + cashCLdepjune + cashCLdepjuly + cashCLdepaug + cashCLdepsep + cashCLdepoct +  cashCLdepnov +
cashCLdepdec + cashCLdepjan + cashCLdepfeb + cashCLdepmarch ;

set totalCLcashdepint = cashCLdepaprlactint + cashCLdepmayactint + cashCLdepjuneactint + cashCLdepjulyactint + cashCLdepaugactint + cashCLdepsepactint + cashCLdepoctactint + cashCLdepnovactint + cashCLdepdecactint + cashCLdepjanactint + cashCLdepfebactint + cashCLdepmarchactint;














































































































 SET shareclosing_bal = shareopening_bal + shareaprl + sharemay + sharejune + sharejuly + shareaug + sharesep + shareoct + sharenov + sharedec + sharejan + sharefeb + sharemarch;
SET cdduction_total = cdductionaprl + cdductionmay + cdductionjune + cdductionjuly + cdductionaug + cdductionsep + cdductionoct + cdductionnov + cdductiondec + cdductionjan + cdductionfeb + cdductionmarch;

SET cdopening_balint = cdopening_bal * 6 / 1200;
