IF (fisrt_fiyear = lastrecovery_cdyear) THEN
   IF(lastrecovery_cdmnth = 4) THEN
        SET  cdacclosingtotal  = cdductionaprltot;        
    END IF;
     IF(lastrecovery_cdmnth = 5) THEN
        SET  cdacclosingtotal  = cdductionmaytot;        
    END IF;
      IF(lastrecovery_cdmnth = 6) THEN
        SET  cdacclosingtotal  = cdductionjunetot;        
    END IF;
    IF(lastrecovery_cdmnth = 7) THEN
        SET  cdacclosingtotal  = cdductionjulytot;        
