        SET  cdacclosingtotal  = cdductionaugtot;        
    END IF;
      IF(lastrecovery_cdmnth = 9) THEN
        SET  cdacclosingtotal  = cdductionseptot;        
    END IF;
       IF(lastrecovery_cdmnth = 10) THEN
        SET  cdacclosingtotal  = cdductionocttot;        
    END IF;
    IF(lastrecovery_cdmnth = 11) THEN
        SET  cdacclosingtotal  = cdductionnovtot;        
    END IF;
   IF(lastrecovery_cdmnth = 12) THEN
        SET  cdacclosingtotal  = cdductiondectot;        
