set totPLinstcashamt = emiPLaprl + emiPLmay + emiPLjune + emiPLjuly + emiPLaug + emiPLsep + emiPLoct + emiPLnov + emiPLdec + emiPLjan + emiPLfeb + emiPLmarch + totalPLcashdep;
