set totPLactintcah = emiPLactintaprl + emiPLactintmay + emiPLactintjune + emiPLactintjuly + emiPLactintaug + emiPLactintsep + emiPLactintoct + emiPLactintnov + emiPLactintdec + emiPLactintjan + emiPLactintfeb + emiPLactintmarch + totalPLcashdepint ;
set totCLinstcashamt = emiCLaprl + emiCLmay + emiCLjune + emiCLjuly + emiCLaug + emiCLsep + emiCLoct + emiCLnov + emiCLdec + emiCLjan + emiCLfeb + emiCLmarch + totalCLcashdep; 
