set totalCLint = emiCLintaprl + emiCLintmay + emiCLintjune + emiCLintjuly + emiCLintaug + emiCLintsep + emiCLintoct + emiCLintnov + emiCLintdec + emiCLintjan + emiCLintfeb + emiCLintmarch ;

set totalcrdeposit = shareclosing_bal + cdacclosingtotal + cdduction_totalint;
set  AOLoanintamt = totPLactintcah - totalPLint;
set AVLoanintamt = totCLactintcash - totalCLint;
set TotLiability = AOLoanClosebal + AVLoanClosebal + AOLoanintamt + AVLoanintamt + suretyamt;

select p_userId as id,varname,shareopening_bal,cdopening_bal,shareaprl,cdductionaprl,cdductionaprltot,sharemay,cdductionmay,cdductionmaytot,sharejune,cdductionjune,cdductionjunetot,sharejuly,cdductionjuly,cdductionjulytot,shareaug,
cdductionaug,cdductionaugtot,sharesep,cdductionsep,cdductionseptot,shareoct,cdductionoct,cdductionocttot,sharenov,cdductionnov,cdductionnovtot,sharedec,cdductiondec,cdductiondectot,sharejan,cdductionjan,cdductionjantot,sharefeb,cdductionfeb,cdductionfebtot,sharemarch,cdductionmarch,cdductionmarchtot,openingloanbal,emirate,emiPLaprl,emiPLintaprl,emiPLaprltot,emiPLactintaprl,emiPLmay,emiPLintmay,emiPLmaytot,emiPLactintmay,emiPLjune,emiPLintjune,emiPLjunetot,emiPLactintjune,emiPLjuly,emiPLintjuly,emiPLjulytot,emiPLactintjuly,emiPLaug,emiPLintaug,emiPLaugtot,emiPLactintaug,emiPLsep,emiPLintsep,emiPLseptot,emiPLactintsep,emiPLoct,emiPLintoct,emiPLocttot,emiPLactintoct,emiPLnov,emiPLintnov,emiPLnovtot,emiPLactintnov,emiPLdec,emiPLintdec,emiPLdectot,emiPLactintdec,emiPLjan,emiPLintjan,emiPLjantot,emiPLactintjan,emiPLfeb,emiPLintfeb,emiPLfebtot,emiPLactintfeb,emiPLmarch,emiPLintmarch,emiPLmarchtot,emiPLactintmarch,shareclosing_bal,cdduction_total,round(cdduction_totalint) as cdduction_totalint,cdacclosingtotal,emiCLopenloan,CLemirate,emiCLaprl,emiCLintaprl,emiCLaprltot,ROUND(TRUNCATE(emiCLactintaprl,3),2) as emiCLactintaprl,emiCLmay,emiCLintmay,emiCLmaytot,ROUND(TRUNCATE(emiCLactintmay,3),2) as emiCLactintmay,emiCLjune,emiCLintjune,emiCLjunetot,ROUND(TRUNCATE(emiCLactintjune,3),2) as emiCLactintjune,emiCLjuly,emiCLintjuly,emiCLjulytot,
ROUND(TRUNCATE(emiCLactintjuly,3),2) as emiCLactintjuly,emiCLaug,emiCLintaug,emiCLaugtot,ROUND(TRUNCATE(emiCLactintaug,3),2) as emiCLactintaug,emiCLsep,emiCLintsep,emiCLseptot,ROUND(TRUNCATE(emiCLactintsep,3),2) as emiCLactintsep,emiCLoct,emiCLintoct,emiCLocttot,ROUND(TRUNCATE(emiCLactintoct,3),2) as emiCLactintoct,emiCLnov,emiCLintnov,emiCLnovtot,ROUND(TRUNCATE(emiCLactintnov,3),2) as emiCLactintnov,emiCLdec,emiCLintdec,emiCLdectot,ROUND(TRUNCATE(emiCLactintdec,3),2) as emiCLactintdec,emiCLjan,emiCLintjan,emiCLjantot,ROUND(TRUNCATE(emiCLactintjan,3),2) as emiCLactintjan,emiCLfeb,emiCLintfeb,emiCLfebtot,ROUND(TRUNCATE(emiCLactintfeb,3),2) as emiCLactintfeb,emiCLmarch,emiCLintmarch,
emiCLmarchtot,ROUND(TRUNCATE(emiCLactintmarch,3),2) as emiCLactintmarch,totalPLcashdep,TRUNCATE(totalPLcashdepint,2) as totalPLcashdepint,totalCLcashdep,TRUNCATE(totalCLcashdepint,2) as totalCLcashdepint,totPLinstcashamt,TRUNCATE(totalPLint,2) as totalPLint,TRUNCATE(totPLactintcah,2) as totPLactintcah,totCLinstcashamt,TRUNCATE(totalCLint,2) as totalCLint,ROUND(TRUNCATE(totCLactintcash,3),2) as totCLactintcash,totalcrdeposit,AOLoanClosebal as AOLoantotalbal,AVLoanClosebal as AVLoantotalbal,ROUND(TRUNCATE(AOLoanintamt,3),2) as AOLoanintamt,ROUND(TRUNCATE(AVLoanintamt,3),2) as AVLoanintamt,varcompany,suretyamt,TRUNCATE(TotLiability,2) as Totliabilityamt,lnDate,lnmonth,loanFirstmaxDate,varcompany1,lnadv,lncontra;

END
