 SELECT
  SUBSTRING_INDEX(SUBSTRING_INDEX(p_audityear, '-', 2), '-', 1) ,
    SUBSTRING_INDEX(SUBSTRING_INDEX(p_audityear, '-', 2), '-', -1)  INTO fisrt_fiyear,second_fiyear;

SELECT  users.id,users.user_id,users.name ,company.company_name INTO id,@varuserid,varname,@varcompany   FROM `users`
INNER join  company on users.company_id = company.company_id
where users.user_id = p_userId;

