  SELECT year(date(max(for_date))) as recovery_year,month(date(max(for_date))) as recovery_mnth,amount INTO lastrecovery_cdyear,lastrecovery_cdmnth,lastrecovery_amount FROM `recovery_data`
where user_id = p_userId and wage_type = '6035';

IF (fisrt_fiyear = lastrecovery_cdyear) THEN
