-- ----------------------------
-- Procedure structure for AuditSettlementID
-- ----------------------------
DROP PROCEDURE IF EXISTS `AuditSettlementID`;
delimiter ;;
CREATE PROCEDURE `AuditSettlementID`(IN `p_userId` INT)
BEGIN
DECLARE varuserid VARCHAR(10);
DECLARE varname VARCHAR(200);
DECLARE varcompany VARCHAR(10);


SELECT  users.user_id,users.name ,company.company_name INTO @varuserid,@varname,@varcompany   FROM `users`
INNER join  company on users.company_id = company.company_id
where users.user_id = p_userId;

select @varuserid userid,@varname name,@varcompany company;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for CalculateDueRecovery
-- ----------------------------
DROP PROCEDURE IF EXISTS `CalculateDueRecovery`;
delimiter ;;
CREATE PROCEDURE `CalculateDueRecovery`(IN `p_forDate` DATE, IN `p_companyId` INT)
BEGIN
    DECLARE v_nextMonth INT;
    DECLARE v_nextYear INT;
    DECLARE v_recoveryStartDate DATE;
    DECLARE v_recoveryEndDate DATE;
    DECLARE done INT DEFAULT FALSE;
    
    DECLARE v_userId VARCHAR(255);
    DECLARE v_loanType VARCHAR(50);
    DECLARE v_interest DOUBLE;
    DECLARE v_cd DOUBLE;
    DECLARE v_share DOUBLE;
    DECLARE v_generatedFor DATE;
    
    DECLARE v_actualCD DOUBLE DEFAULT 0;
    DECLARE v_actualShare DOUBLE DEFAULT 0;
    DECLARE v_actualLoanInterest DOUBLE DEFAULT 0;
    
    DECLARE v_cdDifference DOUBLE;
    DECLARE v_shareDifference DOUBLE;
    DECLARE v_loanDifference DOUBLE;
    
    DECLARE interest_cursor CURSOR FOR
        SELECT user_id, loan_type, interest, cd, share, generated_for
        FROM interest_on_loan
        WHERE DATE(generated_for) = p_forDate
        AND company_id = p_companyId;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    
    SET v_nextMonth = MONTH(p_forDate) + 1;
    SET v_nextYear = YEAR(p_forDate);
    
    IF v_nextMonth > 12 THEN
        SET v_nextMonth = 1;
        SET v_nextYear = v_nextYear + 1;
    END IF;
    
    SET v_recoveryStartDate = DATE(CONCAT(v_nextYear, '-', LPAD(v_nextMonth, 2, '0'), '-01'));
    SET v_recoveryEndDate = LAST_DAY(v_recoveryStartDate);
    
    
    DELETE FROM due_recovery 
    WHERE DATE(for_date) = p_forDate 
    AND ABS(amount) <= 0.01;
    
    OPEN interest_cursor;
    
    read_loop: LOOP
        FETCH interest_cursor INTO v_userId, v_loanType, v_interest, v_cd, v_share, v_generatedFor;
        
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SET v_actualCD = 0;
        SET v_actualShare = 0;
        SET v_actualLoanInterest = 0;
        
        
        IF p_companyId IN (101, 102, 103) THEN
            
            SELECT COALESCE(SUM(amount), 0) INTO v_actualCD
            FROM recovery_data
            WHERE user_id = v_userId
            AND wage_type = '6035'
            AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            
            
            SELECT COALESCE(SUM(amount), 0) INTO v_actualShare
            FROM recovery_data
            WHERE user_id = v_userId
            AND wage_type = '6030'
            AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            
            
            IF v_loanType = 'COMMODITY' THEN
                SELECT COALESCE(SUM(amount), 0) INTO v_actualLoanInterest
                FROM recovery_data
                WHERE user_id = v_userId
                AND wage_type = '6015'
                AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            ELSE
                SELECT COALESCE(SUM(amount), 0) INTO v_actualLoanInterest
                FROM recovery_data
                WHERE user_id = v_userId
                AND wage_type = '6025'
                AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            END IF;
            
        ELSEIF p_companyId = 104 THEN
            
            SELECT COALESCE(SUM(amount), 0) INTO v_actualCD
            FROM recovery_data
            WHERE user_id = v_userId
            AND wage_type = '4220'
            AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            
            
            SET v_actualShare = 0;
            
            
            IF v_loanType = 'COMMODITY' THEN
                SELECT COALESCE(SUM(amount), 0) INTO v_actualLoanInterest
                FROM recovery_data
                WHERE user_id = v_userId
                AND wage_type = '4270'
                AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            ELSE
                SELECT COALESCE(SUM(amount), 0) INTO v_actualLoanInterest
                FROM recovery_data
                WHERE user_id = v_userId
                AND wage_type = '4250'
                AND DATE(for_date) BETWEEN v_recoveryStartDate AND v_recoveryEndDate;
            END IF;
        END IF;
        
        
        SET v_cdDifference = v_cd - v_actualCD;
        SET v_shareDifference = v_share - v_actualShare;
        SET v_loanDifference = v_interest - v_actualLoanInterest;
        
        
        IF ABS(v_cdDifference) > 0.01 THEN
            CALL InsertOrUpdateDueRecovery(v_userId, p_forDate, v_generatedFor, 
                CASE WHEN p_companyId IN (101, 102, 103) THEN '6035' ELSE '4220' END, 
                v_cdDifference);
        END IF;
        
        
        IF ABS(v_shareDifference) > 0.01 AND p_companyId IN (101, 102, 103) THEN
            CALL InsertOrUpdateDueRecovery(v_userId, p_forDate, v_generatedFor, '6030', v_shareDifference);
        END IF;
        
        
        IF ABS(v_loanDifference) > 0.01 THEN
            SET @wageType = CASE 
                WHEN p_companyId IN (101, 102, 103) AND v_loanType = 'COMMODITY' THEN '6015'
                WHEN p_companyId IN (101, 102, 103) THEN '6025'
                WHEN p_companyId = 104 AND v_loanType = 'COMMODITY' THEN '4270'
                ELSE '4250'
            END;
            CALL InsertOrUpdateDueRecovery(v_userId, p_forDate, v_generatedFor, @wageType, v_loanDifference);
        END IF;
        
    END LOOP;
    
    CLOSE interest_cursor;
    
    
    SELECT 
        COUNT(*) as total_due_records,
        SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END) as total_pending_amount,
        SUM(CASE WHEN amount < 0 THEN ABS(amount) ELSE 0 END) as total_excess_recovery
    FROM due_recovery 
    WHERE DATE(for_date) = p_forDate;
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for calculate_cd_interest
-- ----------------------------
DROP PROCEDURE IF EXISTS `calculate_cd_interest`;
delimiter ;;
CREATE PROCEDURE `calculate_cd_interest`()
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE userId VARCHAR(255);
    DECLARE cd_total DOUBLE;
    DECLARE cd_interest DOUBLE DEFAULT 0;
    DECLARE previous_interest_total DOUBLE DEFAULT 0;
    DECLARE new_interest DOUBLE DEFAULT 0;
    DECLARE share_deduction DOUBLE DEFAULT 0;
    DECLARE total_share_deduction DOUBLE DEFAULT 0; 
    DECLARE interest_log_exists INT;

    DECLARE user_cursor CURSOR FOR 
        SELECT DISTINCT user_id 
        FROM cd_share_deductions;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN user_cursor;

    read_loop: LOOP
        FETCH user_cursor INTO userId;
        
        IF done THEN
            LEAVE read_loop;
        END IF;

        
        SELECT COUNT(*) INTO interest_log_exists
        FROM cd_share_deductions
        WHERE user_id = userId 
          AND MONTH(payment_date) = MONTH(CURDATE()) 
          AND YEAR(payment_date) = YEAR(CURDATE());

        IF interest_log_exists = 0 THEN

            SELECT 
                COALESCE(MAX(cd_interest_total), 0) INTO previous_interest_total 
            FROM cd_share_deductions
            WHERE user_id = userId
              AND payment_date >= DATE_FORMAT(NOW() - INTERVAL 1 MONTH, '%Y-%m-01') 
              AND payment_date < DATE_FORMAT(NOW(), '%Y-%m-01');

            SELECT 
                COALESCE(MAX(cd_deduction_total), 0) INTO cd_total
            FROM cd_share_deductions
            WHERE user_id = userId
              AND payment_date >= DATE_FORMAT(NOW() - INTERVAL 2 MONTH, '%Y-%m-01') 
              AND payment_date < DATE_FORMAT(NOW(), '%Y-%m-01');

            SET cd_interest = cd_total * 0.005;
            SET new_interest = previous_interest_total + cd_interest;

                user_id,
                cd_deduction,
                cd_deduction_total,
                created_at,
                payment_date,
                share_deduction,
                share_deduction_total,
                total_deduction,
                cd_deduction_generated, 
                share_deduction_generated,
                cd_interest,
                cd_interest_total
            )
            VALUES (
                userId,
                0,
                cd_total,
                CURDATE(),
                CURDATE(),                 
                0,
                0,
                0,
                0, 
                0, 
                cd_interest, 
                new_interest
            );
                user_id,
                log_month,
                interest,
                interest_total,
                created_at
            )
            VALUES (
                userId,
                CURDATE(),
                cd_interest,
                new_interest,
                NOW()
            );
        END IF;

    END LOOP;
    
    CLOSE user_cursor;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for CancleAdvice2
-- ----------------------------
DROP PROCEDURE IF EXISTS `CancleAdvice2`;
delimiter ;;
CREATE PROCEDURE `CancleAdvice2`(IN `input_id` VARCHAR(20))
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE input_gid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_uid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_loan_type TINYINT(4);
    DECLARE lv_user_id VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_payment_type TINYINT(4);
    DECLARE lv_payment_bank VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_amount DOUBLE;
    DECLARE lv_name VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;

    
    DECLARE cur CURSOR FOR
        SELECT bond_id, loan_type, user_id, payment_type, payment_bank, amount FROM loan_voucher WHERE gid = input_gid;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    SELECT gid INTO input_gid
    FROM loan_voucher
    WHERE bond_id = input_uid
    LIMIT 1;

    IF input_gid IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No GID found for input UID';
    END IF;

    
    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO lv_uid, lv_loan_type, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SELECT name INTO lv_name FROM users WHERE user_id = lv_user_id;

        VALUES ('Cancelled', 0, lv_name, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount, lv_loan_type, lv_uid, input_gid, 4, NOW());
    END LOOP;

    CLOSE cur;

    
    UPDATE loan_voucher
    SET advice_downloaded = 1,
        advice_approved = 0
    WHERE gid = input_gid
      AND bond_id <> input_uid;

END
;;
delimiter ;

-- ----------------------------
-- Function structure for find_balance
-- ----------------------------
DROP FUNCTION IF EXISTS `find_balance`;
delimiter ;;
CREATE FUNCTION `find_balance`(`user_id` INT, `year_in` INT, `month_in` INT)
 RETURNS double
BEGIN
DECLARE bal DOUBLE;
SELECT COALESCE(
    (
      SELECT (l.loan_balance+l.loan_repaid)
      FROM loans l
      WHERE l.user_id = user_id
        AND YEAR(l.loan_approve_date) = year_in
        AND MONTH(l.loan_approve_date) = month_in
        AND DAY(l.loan_approve_date) BETWEEN 1 AND 18
      ORDER BY l.loan_approve_date
      LIMIT 1
    ),
    (
      SELECT e.principal_remaing
      FROM emi_payments_details e
      WHERE e.user_id = user_id
        AND YEAR(e.payment_date) = year_in
        AND MONTH(e.payment_date) = month_in
      ORDER BY e.payment_date
      LIMIT 1
    )
    
    
) INTO bal;

IF bal IS NULL THEN
        SET bal = 0;
    END IF;


RETURN bal;
END
;;
delimiter ;

-- ----------------------------
-- Function structure for find_instalment
-- ----------------------------
DROP FUNCTION IF EXISTS `find_instalment`;
delimiter ;;
CREATE FUNCTION `find_instalment`(`user_id` VARCHAR(15), `loan_type` INT, `month_in` INT, `year_in` INT)
 RETURNS double
  READS SQL DATA 
BEGIN
    DECLARE instalment DOUBLE;

    SELECT COALESCE(
        (
            SELECT e.emi_amount
            FROM emi_payments_details e
            WHERE MONTH(e.payment_date) = month_in
              AND YEAR(e.payment_date) = year_in
              AND e.loan_type = loan_type
              AND e.user_id = user_id
            LIMIT 1
        ),
        (
            SELECT 
                CASE 
                    WHEN loan_type = 0 THEN u.personal_loan_emi 
                    ELSE u.commodity_loan_emi 
                END
            FROM users u
            WHERE u.user_id = user_id
            LIMIT 1
        )
    ) INTO instalment;
    
    IF instalment IS NULL THEN
        SET instalment = 0;
    END IF;


    RETURN instalment;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for GetCompanyId
-- ----------------------------
DROP PROCEDURE IF EXISTS `GetCompanyId`;
delimiter ;;
CREATE PROCEDURE `GetCompanyId`(IN `p_companyName` VARCHAR(50), OUT `p_companyId` INT)
BEGIN
    SET p_companyId = CASE 
        WHEN p_companyName = 'TML' THEN 101
        WHEN p_companyName = 'TMLBSL' THEN 102
        WHEN p_companyName = 'TTL' THEN 103
        WHEN p_companyName = 'TCN' THEN 104
        ELSE 0
    END;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Insertorupdatebanks
-- ----------------------------
DROP PROCEDURE IF EXISTS `Insertorupdatebanks`;
delimiter ;;
CREATE PROCEDURE `Insertorupdatebanks`(IN `p_userId` VARCHAR(20), IN `p_accountnum` VARCHAR(25), IN `p_bankname` VARCHAR(50), IN `p_branchname` VARCHAR(50), IN `p_ifsccode` VARCHAR(20), IN `p_payableat` VARCHAR(50))
BEGIN
    IF EXISTS (SELECT 1 FROM banks 
               WHERE user_id = p_userId 
              ) THEN
       UPDATE banks 
        SET account_num = p_accountnum,
            bank_name = p_bankname,
            branch_name = p_branchname, ifsc_code =p_ifsccode, payable_at =p_payableat
        WHERE user_id = p_userId; 
    ELSE
;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for InsertOrUpdateDueRecovery
-- ----------------------------
DROP PROCEDURE IF EXISTS `InsertOrUpdateDueRecovery`;
delimiter ;;
CREATE PROCEDURE `InsertOrUpdateDueRecovery`(IN `p_userId` VARCHAR(255), IN `p_forDate` DATE, IN `p_generatedFor` DATE, IN `p_wageType` VARCHAR(10), IN `p_amount` DOUBLE)
BEGIN
    IF EXISTS (SELECT 1 FROM due_recovery 
               WHERE user_id = p_userId 
               AND DATE(for_date) = p_forDate 
               AND wage_type = p_wageType) THEN
        UPDATE due_recovery 
        SET amount = p_amount
        WHERE user_id = p_userId 
        AND DATE(for_date) = p_forDate 
        AND wage_type = p_wageType;
    ELSE
        VALUES (p_userId, p_wageType, p_amount, p_generatedFor);
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for interest_calculator
-- ----------------------------
DROP PROCEDURE IF EXISTS `interest_calculator`;
delimiter ;;
CREATE PROCEDURE `interest_calculator`(IN `input_month` INT, IN `company_id` INT, IN `input_year` INT, IN `input_date` INT)
BEGIN
    DECLARE cnt INT DEFAULT 0;
    DECLARE generated_date DATE;
    DECLARE prev_month INT;
    DECLARE prev_year INT;
    DECLARE last_cutoff_date INT DEFAULT 18; 
    DECLARE current_cutoff_date INT;

    
    SET generated_date = STR_TO_DATE(CONCAT(input_year, '-', input_month, '-01'), '%Y-%m-%d');
    SET prev_month = MONTH(DATE_SUB(generated_date, INTERVAL 1 MONTH));
    SET prev_year = YEAR(DATE_SUB(generated_date, INTERVAL 1 MONTH));
    SET current_cutoff_date = input_date;

    
    SELECT IFNULL(DAY(date_of_report), 18) INTO last_cutoff_date
    FROM date_of_emi_report 
    WHERE company_id = company_id 
    ORDER BY date_of_report DESC 
    LIMIT 1;

    
    SELECT COUNT(*) INTO cnt 
    FROM interest_on_loan i
    WHERE MONTH(i.generated_for) = input_month 
      AND YEAR(i.generated_for) = input_year 
      AND i.company_id = company_id;

    
    IF cnt = 0 THEN

        
        SELECT 
            l.id, 
            (SELECT cd_cut FROM users WHERE user_id=l.user_id),
            (SELECT share_cut FROM users WHERE user_id=l.user_id),
            ROUND(
                ((l.loan_balance + l.loan_repaid) * l.intrest_rate * 
                (DAY(LAST_DAY(generated_date)) - DAY(l.loan_approve_date))
                / 36000), 2
            ) AS interest,
            l.user_id,
            generated_date,
            (SELECT find_instalment(l.user_id, l.loan_type, input_month, input_year)) AS instalment,
            l.loan_type,
            (SELECT find_balance(l.user_id, input_year, input_month)) AS loan_balance,
            CURRENT_DATE,
            (SELECT name FROM users u WHERE u.user_id = l.user_id),
            company_id
        FROM loans l
        JOIN users u ON l.user_id = u.user_id
        WHERE l.loan_status = 3
          AND u.company_id = company_id
          AND MONTH(l.loan_approve_date) = input_month
          AND YEAR(l.loan_approve_date) = input_year
          AND DAY(l.loan_approve_date) BETWEEN 1 AND current_cutoff_date;

        
        SELECT 
            l.id,
            ROUND(
                (
                    
                    (COALESCE(
                        
                        (SELECT e.principal_remaing
                         FROM emi_payments_details e
                         WHERE e.user_id = l.user_id
                         AND e.loan_type = l.loan_type
                         AND MONTH(e.payment_date) = input_month
                         AND YEAR(e.payment_date) = input_year
                         ORDER BY e.payment_date DESC
                         LIMIT 1),
                        
                        
                        (SELECT e.principal_remaing
                         FROM emi_payments_details e
                         WHERE e.user_id = l.user_id
                         AND e.loan_type = l.loan_type
                         ORDER BY e.payment_date DESC
                         LIMIT 1),
                        
                        
                        l.loan_balance,
                        
                        
                        l.loan_amount
                    ) * l.intrest_rate * 30) / 36000
                    
                    
                    - IFNULL((
                        SELECT SUM(
                            
                            (ep.emi_amount * l.intrest_rate * 
                            (DAY(LAST_DAY(STR_TO_DATE(CONCAT(prev_year, '-', prev_month, '-01'), '%Y-%m-%d'))) - 
                             DAY(ep.payment_date) + 1)) / 36000
                        )
                        FROM emi_payments_details ep
                        WHERE ep.user_id = l.user_id
                        AND ep.loan_type = l.loan_type
                        AND MONTH(ep.payment_date) = prev_month
                        AND YEAR(ep.payment_date) = prev_year
                        AND DAY(ep.payment_date) > last_cutoff_date
                        AND ep.emi_payment_type = 1
                    ), 0)
                    
                    
                    - IFNULL((
                        SELECT SUM(
                            
                            (ep.emi_amount * l.intrest_rate * 
                            (current_cutoff_date - DAY(ep.payment_date) + 1)) / 36000
                        )
                        FROM emi_payments_details ep
                        WHERE ep.user_id = l.user_id
                        AND ep.loan_type = l.loan_type
                        AND MONTH(ep.payment_date) = input_month
                        AND YEAR(ep.payment_date) = input_year
                        AND DAY(ep.payment_date) < current_cutoff_date
                        AND ep.emi_payment_type = 1
                    ), 0)
                    +
                    
                    IFNULL((
                        SELECT 
                            ((e.loan_balance + e.loan_repaid - e.loan_amount) * l.intrest_rate * (DAY(e.loan_approve_date) - 1) / 36000)
                        FROM loans e
                        WHERE e.user_id = l.user_id
                          AND e.loan_status = 3
                          AND MONTH(e.loan_approve_date) = prev_month
                          AND YEAR(e.loan_approve_date) = prev_year
                          AND DAY(e.loan_approve_date) BETWEEN 1 AND last_cutoff_date
                          LIMIT 1
                    ), 0)
                    +
                    
                    IFNULL((
                        SELECT 
                            (e.loan_amount * l.intrest_rate * 
                            (DAY(LAST_DAY(DATE_SUB(generated_date, INTERVAL 1 MONTH))) - DAY(e.loan_approve_date) + 1) / 36000)
                        FROM loans e
                        WHERE e.user_id = l.user_id
                          AND e.loan_status = 3
                          AND MONTH(e.loan_approve_date) = prev_month
                          AND YEAR(e.loan_approve_date) = prev_year
                          AND DAY(e.loan_approve_date) BETWEEN (last_cutoff_date + 1) AND DAY(LAST_DAY(DATE_SUB(generated_date, INTERVAL 1 MONTH)))
                          LIMIT 1
                    ), 0)
                ), 2
            ) AS interest,
            l.user_id,
            generated_date,
            (SELECT find_instalment(l.user_id, l.loan_type, input_month, input_year)) AS instalment,
            l.loan_type,
            (SELECT find_balance(l.user_id, input_year, input_month)) AS loan_balance,
            CURRENT_DATE,
            (SELECT name FROM users u WHERE u.user_id = l.user_id),
            company_id
        FROM loans l
        JOIN users u ON l.user_id = u.user_id
        WHERE l.loan_status = 3
          AND u.company_id = company_id
          AND NOT (
              MONTH(l.loan_approve_date) = input_month 
              AND YEAR(l.loan_approve_date) = input_year
              AND DAY(l.loan_approve_date) BETWEEN 1 AND current_cutoff_date
          );

        
        VALUES (company_id, STR_TO_DATE(CONCAT(input_year, '-', input_month, '-', current_cutoff_date), '%Y-%m-%d'))
        ON DUPLICATE KEY UPDATE 
        date_of_report = STR_TO_DATE(CONCAT(input_year, '-', input_month, '-', current_cutoff_date), '%Y-%m-%d');

        
        SELECT *
        FROM interest_on_loan i
        WHERE MONTH(i.generated_for) = input_month 
          AND YEAR(i.generated_for) = input_year
          AND i.company_id = company_id;

    ELSE
        
        SELECT *
        FROM interest_on_loan i
        WHERE MONTH(i.generated_for) = input_month 
          AND YEAR(i.generated_for) = input_year
          AND i.company_id = company_id;
    END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for loan_end
-- ----------------------------
DROP PROCEDURE IF EXISTS `loan_end`;
delimiter ;;
CREATE PROCEDURE `loan_end`()
BEGIN

UPDATE loans l
    SET l.loan_status = 5,
        l.updated_at = NOW()
    WHERE l.loan_balance = 0
      AND l.loan_status != 5
      AND l.loan_status IN (3,6);

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessAdvice
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessAdvice`;
delimiter ;;
CREATE PROCEDURE `ProcessAdvice`(IN `input_bid` VARCHAR(25))
BEGIN 
	DECLARE loan_category VARCHAR(50);
    DECLARE loan_amount DOUBLE;
    DECLARE loan_balance DOUBLE;
    DECLARE user_id VARCHAR(50);
    DECLARE category_val VARCHAR(50);
    DECLARE name_val VARCHAR(100);
    DECLARE bank_name VARCHAR(100);
    DECLARE cheque_no VARCHAR(100);
    DECLARE bank_name1 VARCHAR(100);
    DECLARE bondtype_val VARCHAR(50);
    DECLARE payment_type TINYINT(4);
    DECLARE approve_date DATETIME;
    DECLARE bank_current_balance DOUBLE DEFAULT 0;
	DECLARE updated_balance DOUBLE;
    
    SELECT lv.user_id, lv.amount, lv.loan_balance, lv.bond_type, lv.payment_type, lv.payment_bank, lv.cheque_no, NOW() INTO user_id, loan_amount, loan_balance, bondtype_val, payment_type, bank_name, cheque_no, approve_date FROM loan_voucher lv 
    WHERE lv.bond_id = input_bid
    LIMIT 1;
    
    SELECT u.name INTO name_val from users u WHERE u.user_id = user_id;
    
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
    
    VALUES (loan_amount, loan_balance, payment_type, approve_date, input_bid, bondtype_val, "MEMBERS", 0, name_val, user_id, cheque_no, bank_name1, 0);
    
        SELECT bank_balance INTO bank_current_balance
        FROM tcos_balance as tb
        WHERE tb.bank_name = bank_name
        LIMIT 1;
        
        SET updated_balance = bank_current_balance - loan_amount;

        UPDATE tcos_balance
        SET bank_balance = updated_balance
        WHERE tcos_balance.bank_name = bank_name;
          
        VALUES (loan_amount, updated_balance, bank_name1, name_val, 0, "MEMBERS", 7, approve_date, input_bid, user_id);
        
        END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessBankTransction
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessBankTransction`;
delimiter ;;
CREATE PROCEDURE `ProcessBankTransction`(IN `transdt` DATETIME)
begin
SELECT  id,transaction_id as trans_id, payment_bank as transname1,transaction_name,amount,transaction_date , CASE WHEN leasuretype = 0 THEN 'Payment' WHEN leasuretype = 1 THEN 'Receipt' WHEN leasuretype = 2 THEN 'Payment' WHEN leasuretype = 3 THEN 'OTHER' END AS leasuretype, CASE WHEN paymenttype = 0 THEN 'NONE' WHEN paymenttype = 1 THEN 'ADVICE' WHEN paymenttype = 2 THEN 'NEFT' WHEN paymenttype = 3 THEN 'CASH' WHEN paymenttype = 4 THEN 'CHEQUE' WHEN paymenttype = 5 THEN 'ONLINE' WHEN paymenttype = 6 THEN 'Receipt' WHEN paymenttype = 7 THEN 'Payment' END AS paymenttype, if(description IS NULL or description = '',transaction_name,description ) as description FROM `transaction_history` where  name != 'Bank Record' and transaction_date >transdt order by transaction_date asc;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessCancelAdvice
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessCancelAdvice`;
delimiter ;;
CREATE PROCEDURE `ProcessCancelAdvice`(IN `input_uid` VARCHAR(25))
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE input_gid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_uid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_loan_type TINYINT(4);
    DECLARE lv_user_id VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_payment_type TINYINT(4);
    DECLARE lv_payment_bank VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_amount DOUBLE;
    DECLARE lv_name VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;

    
    DECLARE cur CURSOR FOR
        SELECT bond_id, loan_type, user_id, payment_type, payment_bank, amount FROM loan_voucher WHERE gid = input_gid;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    SELECT gid INTO input_gid
    FROM loan_voucher
    WHERE bond_id = input_uid
    LIMIT 1;

    IF input_gid IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No GID found for input UID';
    END IF;

    
    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO lv_uid, lv_loan_type, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SELECT name INTO lv_name FROM users WHERE user_id = lv_user_id;

        VALUES ('Cancelled', 0, lv_name, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount, lv_loan_type, lv_uid, input_gid, 4, NOW());
    END LOOP;

    CLOSE cur;

    
    UPDATE loan_voucher
    SET advice_downloaded = 0,
        advice_approved = 0
    WHERE gid = input_gid
      AND bond_id <> input_uid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessCancelVoc
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessCancelVoc`;
delimiter ;;
CREATE PROCEDURE `ProcessCancelVoc`(IN `input_vid` VARCHAR(25))
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE input_gid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_uid VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_loan_type TINYINT(4);
    DECLARE lv_user_id VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_payment_type TINYINT(4);
    DECLARE lv_payment_bank VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_category VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE lv_amount DOUBLE;
    DECLARE lv_name VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;

    
    DECLARE cur CURSOR FOR
        SELECT mv.v_id, mv.user_id, mv.paymenttype, mv.payment_bank, mv.total_amount, mv.name, mv.category FROM member_voucher as mv WHERE gid = input_gid;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    SELECT gid INTO input_gid
    FROM member_voucher
    WHERE v_id = input_vid
    LIMIT 1;

    IF input_gid IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No GID found for input UID';
    END IF;

    
    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO lv_uid, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount, lv_name, lv_category;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        IF lv_category = 'MEMBERS' THEN
            SET lv_loan_type = 2;
        ELSEIF lv_category = 'EMPLOYEE' THEN
            SET lv_loan_type = 3;
        ELSEIF lv_category = 'VENDOR' THEN
            SET lv_loan_type = 4;
        ELSE
            SET lv_loan_type = 5;
        END IF;

        VALUES ('Cancelled', 2, lv_name, lv_user_id, lv_payment_type, lv_payment_bank, lv_amount, lv_loan_type, lv_uid, input_gid, 4, NOW());
    END LOOP;

    CLOSE cur;

    
    UPDATE member_voucher
    SET voucher_downloaded = 0,
        voucher_approved = 0
    WHERE gid = input_gid
      AND v_id <> input_vid;

END
;;
delimiter ;

