-- ----------------------------
-- Procedure structure for ProcessCashier
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessCashier`;
delimiter ;;
CREATE PROCEDURE `ProcessCashier`(IN `uid` VARCHAR(50))
BEGIN
    DECLARE uuid VARCHAR(50);
    DECLARE leasure_type TINYINT(4) DEFAULT 0;
    DECLARE loan_type TINYINT(4);
    DECLARE payment_type TINYINT(4);
    DECLARE gid VARCHAR(50);
    DECLARE name VARCHAR(50);
    DECLARE payment_bank VARCHAR(50);
    DECLARE user_id VARCHAR(50);
    DECLARE amount DOUBLE;
    DECLARE prefix VARCHAR(3);
    DECLARE last_uuid VARCHAR(50);
    DECLARE number_part INT;
    DECLARE formatted_number VARCHAR(5);

    
    SELECT lv.loan_type, lv.gid, lv.user_id, lv.amount, lv.payment_type, lv.payment_bank
    INTO loan_type, gid, user_id, amount, payment_type, payment_bank
    FROM loan_voucher as lv
    WHERE lv.bond_id = uid;   

    
    IF EXISTS (SELECT 1 FROM users u WHERE u.user_id = user_id) THEN
        SELECT u.name INTO name FROM users u WHERE u.user_id = user_id;
    ELSE
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'User not found.';
    END IF;

    
    IF loan_type = 0 THEN
        SET prefix = 'PPB';
    ELSEIF loan_type = 1 THEN
        SET prefix = 'PCB';
    ELSE
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Unsupported loan_type. Must be 0 or 1.';
    END IF;

    
    SELECT c.uuid INTO last_uuid
    FROM cashier c
    WHERE c.loan_type = loan_type AND c.leasure_type = 0
    ORDER BY c.updated_date DESC
    LIMIT 1;
    
    IF last_uuid IS NULL THEN
        SET uuid = CONCAT(prefix, '00001');
    ELSE
        SET number_part = CAST(SUBSTRING(last_uuid, 4) AS UNSIGNED);
        SET number_part = number_part + 1;
        SET formatted_number = LPAD(number_part, 5, '0');
        SET uuid = CONCAT(prefix, formatted_number);
    END IF;

    
    VALUES (uuid, 0, user_id, name, payment_bank, payment_type, amount, loan_type, uid, gid, 0, NOW());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessCashier1
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessCashier1`;
delimiter ;;
CREATE PROCEDURE `ProcessCashier1`(IN `uid` VARCHAR(50))
BEGIN
    DECLARE uuid VARCHAR(50);
    DECLARE leasure_type TINYINT(4) DEFAULT 0;
    DECLARE loan_type TINYINT(4);
    DECLARE payment_type TINYINT(4);
    DECLARE gid VARCHAR(50);
    DECLARE name VARCHAR(50);
    DECLARE payment_bank VARCHAR(50);
    DECLARE user_id VARCHAR(50);
    DECLARE amount DOUBLE;
    DECLARE prefix VARCHAR(4);
    DECLARE last_uuid VARCHAR(50);
    DECLARE category VARCHAR(50);
    DECLARE num_part INT;

    
    SELECT lv.gid, lv.user_id, lv.total_amount, lv.paymenttype, lv.payment_bank, lv.name, lv.category
    INTO gid, user_id, amount, payment_type, payment_bank, name, category
    FROM member_voucher lv
    WHERE lv.v_id = uid
    LIMIT 1;
    
    
    SET prefix = 'UVOC';

    
    SELECT c.uuid INTO last_uuid
    FROM cashier c
    WHERE c.leasure_type = 2
    ORDER BY c.updated_date DESC
    LIMIT 1;

    IF last_uuid IS NULL THEN
        SET uuid = CONCAT(prefix, '00001');
    ELSE
        SET num_part = CAST(SUBSTRING(last_uuid, 5) AS UNSIGNED);
        SET num_part = num_part + 1;
        SET uuid = CONCAT(prefix, LPAD(num_part, 5, '0'));
    END IF;
    
    
    IF category = 'MEMBERS' THEN
        SET loan_type = 2;
    ELSEIF category = 'EMPLOYEE' THEN
        SET loan_type = 3;
    ELSEIF category = 'VENDOR' THEN
        SET loan_type = 4;
    ELSE
        SET loan_type = 5;
    END IF;

    
    VALUES (uuid, 2, user_id, name, payment_bank, payment_type, amount, loan_type, uid, gid, 0, NOW());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessReceipt
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessReceipt`;
delimiter ;;
CREATE PROCEDURE `ProcessReceipt`(IN `input_rid` VARCHAR(25))
BEGIN
    DECLARE receipt_category VARCHAR(50);
    DECLARE vsln_value VARCHAR(10);
    DECLARE done INT DEFAULT FALSE;
    
    DECLARE receipt_amount DOUBLE;
    DECLARE user_id VARCHAR(50);
    DECLARE category_val VARCHAR(50);
    DECLARE name_val VARCHAR(100);
    DECLARE cheque_no VARCHAR(50);
    DECLARE description VARCHAR(150);
    DECLARE bank_name1 VARCHAR(100);
    DECLARE bank_name VARCHAR(100);
    DECLARE vouchertype_val VARCHAR(50);
    DECLARE payment_type TINYINT(4);
    DECLARE approve_date DATETIME;
    DECLARE new_share_total DOUBLE;
    DECLARE new_comm_total DOUBLE;
    DECLARE new_pers_total DOUBLE;
    DECLARE bank_current_balance DOUBLE DEFAULT 0;
	DECLARE updated_balance DOUBLE;
    DECLARE share_value VARCHAR(50);
    
    DECLARE cur CURSOR FOR 
    	SELECT v_sln FROM receipt WHERE v_id = input_rid;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    
    SELECT category INTO receipt_category
    FROM member_receipt
    WHERE r_id = input_rid AND stage = 2
    LIMIT 1;
    
    IF receipt_category = 'MEMBERS' THEN
        
        SELECT 'Processing MEMBER receipt' AS message;
        
        SELECT m.user_id, m.category, m.name, m.paymenttype, NOW(), m.cheque_no, m.description, m.payment_bank 
        INTO user_id, category_val, name_val, payment_type, approve_date, cheque_no, description, bank_name
        FROM member_receipt m WHERE m.r_id = input_rid LIMIT 1;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        OPEN cur;
        receipt_loop: LOOP
            FETCH cur INTO vsln_value;
            IF done THEN
                LEAVE receipt_loop;
            END IF;

            
            IF vsln_value = 'A0001' THEN
                SELECT 'Executing logic for A0001 (ADM FEE)' AS action;
                        
                        SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'A0001' LIMIT 1;
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'A0001' LIMIT 1;

                         VALUES (
                             user_id, category_val, name_val,1, input_rid,
                             vouchertype_val, payment_type, receipt_amount, 0, approve_date, cheque_no, description, bank_name1, 0);

            ELSEIF vsln_value = 'S0003' THEN
                SELECT 'Executing logic for S0003 (Share Balance)' AS action;

                        
                        SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'S0003' LIMIT 1;
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'S0003' LIMIT 1;
                        SELECT COUNT(share_deduction) INTO share_value FROM `cd_share_deductions`
                      WHERE   cd_share_deductions.user_id = user_id;
                       
                         IF share_value = '0' THEN
                        SET   new_share_total = receipt_amount;
                        
                    ELSE   
                        UPDATE cd_share_deductions
                            SET 
                                share_deduction_total = share_deduction_total + receipt_amount,
                                total_deduction = total_deduction + receipt_amount,
                                payment_date = approve_date
                            WHERE cd_share_deductions.user_id = user_id;
                    END IF;    
                                SELECT share_deduction_total
                                INTO new_share_total
                                FROM cd_share_deductions
                                WHERE cd_share_deductions.user_id = user_id
                                ORDER BY cd_share_deductions.payment_date DESC
                                LIMIT 1;
                                
                                    user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2)
                                VALUES (
                                    user_id, category_val, name_val,1, input_rid,
                                    vouchertype_val, payment_type, receipt_amount, new_share_total, approve_date, cheque_no, description, bank_name1, 0);

            ELSEIF vsln_value = 'C0003' THEN
                SELECT 'Executing logic for C0003 (COMM LOAN)' AS action;

                        
                        SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'C0003' LIMIT 1;
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'C0003' LIMIT 1;
                            
                            UPDATE loans
                            JOIN (
                                SELECT id
                                FROM loans
                                WHERE loans.user_id = user_id AND loan_type = 1
                                ORDER BY loan_approve_date DESC
                                LIMIT 1
                            ) AS sub ON loans.id = sub.id
                            SET 
                                loan_balance = loan_balance - receipt_amount,
                                loan_repaid = loan_repaid + receipt_amount;
                            
                            SELECT loan_balance
                            INTO new_comm_total
                            FROM loans
                            WHERE loans.user_id = user_id AND loans.loan_type = 1
                            ORDER BY loans.loan_approve_date DESC
                            LIMIT 1;
                                
                                    user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2)
                                VALUES (
                                    user_id, category_val, name_val,1, input_rid,
                                    vouchertype_val, payment_type, receipt_amount, new_comm_total, approve_date, cheque_no, description, bank_name1, 0);

            ELSEIF vsln_value = 'L0015' THEN
                SELECT 'Executing logic for L0015' AS action;

                        
                        SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'L0015' LIMIT 1; 
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'L0015' LIMIT 1;
                        
                        UPDATE loans
                            JOIN (
                                SELECT id
                                FROM loans
                                WHERE loans.user_id = user_id AND loan_type = 0
                                ORDER BY loan_approve_date DESC
                                LIMIT 1
                            ) AS sub ON loans.id = sub.id
                            SET 
                                loan_balance = loan_balance - receipt_amount,
                                loan_repaid = loan_repaid + receipt_amount;
                            
                            SELECT loan_balance
                            INTO new_pers_total
                            FROM loans
                            WHERE loans.user_id = user_id AND loans.loan_type = 0
                            ORDER BY loans.loan_approve_date DESC
                            LIMIT 1;
                                
                                    user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2)
                                VALUES (
                                    user_id, category_val, name_val,1, input_rid,
                                    vouchertype_val, payment_type, receipt_amount, new_pers_total, approve_date, cheque_no, description, bank_name1, 0);
                                
			  ELSEIF vsln_value = 'I0005' THEN
                SELECT 'Int on Com Loan for I0005' AS action;

                        
                        SELECT r.amount, r.vouchertype INTO receipt_amount, vouchertype_val
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'I0005' LIMIT 1; 
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'I0005' LIMIT 1;
                        
                        UPDATE loans
                            JOIN (
                                SELECT id
                                FROM loans
                                WHERE loans.user_id = user_id AND loan_type = 1
                                ORDER BY loan_approve_date DESC
                                LIMIT 1
                            ) AS sub ON loans.id = sub.id
                            SET 
                                interest_diff = interest_diff - receipt_amount;
                            
                            SELECT interest_diff
                            INTO new_pers_total
                            FROM loans
                            WHERE loans.user_id = user_id AND loans.loan_type = 1
                            ORDER BY loans.loan_approve_date DESC
                            LIMIT 1;
                                
                                    user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2)
                                VALUES (
                                    user_id, category_val, name_val,1, input_rid,
                                    vouchertype_val, payment_type, receipt_amount, new_pers_total, approve_date, cheque_no, description, bank_name1, 0
                                );
                                
			ELSEIF vsln_value = 'I0011' THEN
                SELECT 'Int on Pers Loan for I0011' AS action;

                        
                        SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = 'I0011' LIMIT 1; 
                        
                        SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = 'I0011' LIMIT 1;
                        
                        UPDATE loans
                            JOIN (
                                SELECT id
                                FROM loans
                                WHERE loans.user_id = user_id AND loan_type = 0
                                ORDER BY loan_approve_date DESC
                                LIMIT 1
                            ) AS sub ON loans.id = sub.id
                            SET 
                                interest_diff = interest_diff - receipt_amount;
                            
                            SELECT interest_diff
                            INTO new_pers_total
                            FROM loans
                            WHERE loans.user_id = user_id AND loans.loan_type = 0
                            ORDER BY loans.loan_approve_date DESC
                            LIMIT 1;
                                
                                    user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2
                                )
                                VALUES (
                                    user_id, category_val, name_val,1, input_rid,
                                    vouchertype_val, payment_type, receipt_amount, new_pers_total, approve_date, cheque_no, description, bank_name1, 0
                                );
            ELSE
                SELECT r.amount INTO receipt_amount
                        FROM receipt r WHERE r.v_id = input_rid AND r.v_sln = vsln_value LIMIT 1;
                        
				     	SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
                 		WHERE aa.sl_no = vsln_value LIMIT 1;
                        
                             user_id, category, name, leasuretype, transaction_id, 
                                    transaction_name, paymenttype, amount, balance, transaction_date, unique_id, description, payment_bank, amount2
                         )
                         VALUES (
                             user_id, category_val, name_val,1, input_rid,
                             vouchertype_val, payment_type, receipt_amount, 0, approve_date, cheque_no, description, bank_name1, 0
                       	 );
            END IF;

        END LOOP;
        CLOSE cur;
        
        SELECT m.user_id, m.name, m.category, m.paymenttype, NOW(), m.total_amount, m.payment_bank
        INTO user_id, name_val, category_val, payment_type, approve_date, receipt_amount, bank_name
        FROM member_receipt m WHERE m.r_id = input_rid LIMIT 1;
        
        SELECT bank_balance INTO bank_current_balance
        FROM tcos_balance as tb
        WHERE tb.bank_name = bank_name
        LIMIT 1;
        
        SET updated_balance = bank_current_balance + receipt_amount;

        UPDATE tcos_balance
        SET bank_balance = updated_balance
        WHERE tcos_balance.bank_name = bank_name;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        VALUES (user_id, name_val, receipt_amount, updated_balance, bank_name1, category_val, 6, 1, input_rid, approve_date);

    ELSE
        
        SELECT 'Processing NON-MEMBER receipt' AS message;
        
        OPEN cur;
        SET done = FALSE;
        receipt_loop1: LOOP
            FETCH cur INTO vsln_value;
            IF done THEN
                LEAVE receipt_loop1;
            END IF;
            
            SELECT r.amount INTO receipt_amount FROM receipt r 
            WHERE r.v_id = input_rid AND r.v_sln = vsln_value LIMIT 1;
            SELECT aa.account_head INTO vouchertype_val FROM account_assign aa 
            WHERE aa.sl_no = vsln_value LIMIT 1;
            SELECT m.category, m.name, m.paymenttype, NOW(), m.cheque_no, m.payment_bank, m.description
            INTO category_val, name_val, payment_type, approve_date, cheque_no, bank_name, description  
            FROM member_receipt m WHERE m.r_id = input_rid LIMIT 1;
            
            IF bank_name = 'State Bank Of India, Telco' THEN
                SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
            ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
                SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
            ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
                SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
            ELSE
                SET bank_name1 = NULL;
            END IF;
            
    		VALUES (NULL, category_val, name_val, 1, input_rid, vouchertype_val, payment_type, receipt_amount, 0, approve_date, cheque_no, description, bank_name1, 0);
            
         END LOOP;
        CLOSE cur;
        
		SELECT m.category, m.name, NOW(), m.total_amount, m.payment_bank
        INTO category_val, name_val, approve_date, receipt_amount, bank_name
        FROM member_receipt m WHERE m.r_id = input_rid LIMIT 1;
        
        SELECT bank_balance INTO bank_current_balance
        FROM tcos_balance as tb
        WHERE tb.bank_name = bank_name
        LIMIT 1;
        
        SET updated_balance = bank_current_balance + receipt_amount;

        UPDATE tcos_balance
        SET bank_balance = updated_balance
        WHERE tcos_balance.bank_name = bank_name;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        VALUES (NULL, name_val, receipt_amount, updated_balance, bank_name1, category_val, 6, 1, input_rid, approve_date);
        
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ProcessVoucher
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProcessVoucher`;
delimiter ;;
CREATE PROCEDURE `ProcessVoucher`(IN `input_vid` VARCHAR(25))
BEGIN
    DECLARE voucher_category VARCHAR(50);
    DECLARE vsln_value VARCHAR(10);
    DECLARE done INT DEFAULT FALSE;
    
    DECLARE voucher_amount DOUBLE;
    DECLARE user_id VARCHAR(50);
    DECLARE category_val VARCHAR(50);
    DECLARE name_val VARCHAR(100);
    DECLARE bank_name1 VARCHAR(100);
    DECLARE cheque_no VARCHAR(100);
    DECLARE description VARCHAR(100);
    DECLARE bank_name VARCHAR(100);
    DECLARE vouchertype_val VARCHAR(50);
    DECLARE payment_type TINYINT(4);
    DECLARE voucher_approved_date DATETIME;
    DECLARE new_share_total DOUBLE;
    DECLARE new_comm_total DOUBLE;
    DECLARE new_pers_total DOUBLE;
    DECLARE bank_current_balance DOUBLE DEFAULT 0;
	DECLARE updated_balance DOUBLE;
    
    DECLARE cur CURSOR FOR 
    	SELECT v_sln FROM voucher WHERE v_id = input_vid;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    
    SELECT category INTO voucher_category
    FROM member_voucher
    WHERE v_id = input_vid AND voucher_approved = 2
    LIMIT 1;
    
    IF voucher_category = 'MEMBERS' THEN
        
        SELECT 'Processing MEMBER voucher' AS message;
        
        SELECT m.user_id, m.category, m.name, m.paymenttype, NOW(), m.cheque_no, m.payment_bank, m.description
        INTO user_id, category_val, name_val, payment_type, voucher_approved_date, cheque_no, bank_name, description
        FROM member_voucher m WHERE m.v_id = input_vid LIMIT 1;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        OPEN cur;
        voucher_loop: LOOP
            FETCH cur INTO vsln_value;
            IF done THEN
                LEAVE voucher_loop;
            END IF;
                        
            SELECT r.amount INTO voucher_amount
            FROM voucher r WHERE r.v_id = input_vid AND r.v_sln = vsln_value LIMIT 1;
            
            SELECT aa.account_head INTO vouchertype_val FROM account_assign aa
            WHERE aa.sl_no = vsln_value LIMIT 1;

            VALUES (user_id, category_val, name_val,2, input_vid, vouchertype_val, payment_type, voucher_amount, 0, voucher_approved_date, cheque_no, description, bank_name1,0);

        END LOOP;
        CLOSE cur;
        
        SELECT m.user_id, m.name, m.category, m.paymenttype, NOW(), m.total_amount, m.payment_bank
        INTO user_id, name_val, category_val, payment_type, voucher_approved_date, voucher_amount, bank_name
        FROM member_voucher m WHERE m.v_id = input_vid LIMIT 1;
        
        SELECT bank_balance INTO bank_current_balance
        FROM tcos_balance as tb
        WHERE tb.bank_name = bank_name
        LIMIT 1;
        
        SET updated_balance = bank_current_balance - voucher_amount;

        UPDATE tcos_balance
        SET bank_balance = updated_balance
        WHERE tcos_balance.bank_name = bank_name;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        VALUES (user_id, voucher_amount, name_val, updated_balance, bank_name1, category_val, 7, 2, input_vid, voucher_approved_date);
        
    ELSE
        
        SELECT 'Processing NON-MEMBER voucher' AS message;
        
        OPEN cur;
        SET done = FALSE;
        voucher_loop1: LOOP
            FETCH cur INTO vsln_value;
            IF done THEN
                LEAVE voucher_loop1;
            END IF;
            
            SELECT r.amount INTO voucher_amount FROM voucher r WHERE r.v_id = input_vid AND r.v_sln = vsln_value LIMIT 1;
            SELECT aa.account_head INTO vouchertype_val FROM account_assign aa WHERE aa.sl_no = vsln_value LIMIT 1;
            SELECT m.category, m.name, m.paymenttype, NOW(), m.cheque_no, m.payment_bank, m.description INTO category_val, name_val, payment_type, voucher_approved_date, cheque_no, bank_name, description FROM member_voucher m WHERE m.v_id = input_vid LIMIT 1;
            
            IF bank_name = 'State Bank Of India, Telco' THEN
                SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
            ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
                SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
            ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
                SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
            ELSE
                SET bank_name1 = NULL;
            END IF;
            
    		VALUES (NULL, category_val, name_val, 2, input_vid, vouchertype_val, payment_type, voucher_amount, 0, voucher_approved_date, cheque_no, description, bank_name1, 0);
            
         END LOOP;
        CLOSE cur;
        
		SELECT m.category, m.name, NOW(), m.total_amount, m.payment_bank
        INTO category_val, name_val, voucher_approved_date, voucher_amount, bank_name
        FROM member_voucher m WHERE m.v_id = input_vid LIMIT 1;
        
        SELECT bank_balance INTO bank_current_balance
        FROM tcos_balance as tb
        WHERE tb.bank_name = bank_name
        LIMIT 1;
        
        SET updated_balance = bank_current_balance - voucher_amount;

        UPDATE tcos_balance
        SET bank_balance = updated_balance
        WHERE tcos_balance.bank_name = bank_name;
        
        IF bank_name = 'State Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-SBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Central Bank Of India, Telco' THEN
            SET bank_name1 = 'BANK-CBI TELCO - MAIN A/c';
        ELSEIF bank_name = 'Jharkhand State Co-operative Bank, Telco' THEN
            SET bank_name1 = 'BANK-JSCB TELCO - MAIN A/c';
        ELSE
            SET bank_name1 = NULL;
        END IF;
        
        VALUES (NULL, voucher_amount, name_val, updated_balance, bank_name1, category_val, 7, 2, input_vid, voucher_approved_date);
             
    END IF;
END
;;
delimiter ;

