-- ----------------------------
-- Triggers structure for table cd_share_deductions
-- ----------------------------
DROP TRIGGER IF EXISTS `before_cd_share_insert`;
delimiter ;;
CREATE TRIGGER `before_cd_share_insert` BEFORE INSERT ON `cd_share_deductions` FOR EACH ROW BEGIN
    DECLARE v_prev_share_total DECIMAL(10,2) DEFAULT 0;
    DECLARE v_prev_cd_total DECIMAL(10,2) DEFAULT 0;

    
    SELECT 
        IFNULL(share_deduction_total, 0),
        IFNULL(cd_deduction_total, 0)
    INTO v_prev_share_total, v_prev_cd_total
    FROM cd_share_deductions
    WHERE user_id = NEW.user_id
    ORDER BY payment_date DESC, id DESC
    LIMIT 1;

    
   SET NEW.share_deduction = IFNULL(NEW.share_deduction, 0);
    SET NEW.cd_deduction = IFNULL(NEW.cd_deduction, 0);

    
    SET NEW.share_deduction_total = v_prev_share_total + NEW.share_deduction;
    SET NEW.cd_deduction_total = v_prev_cd_total + NEW.cd_deduction;

    
    SET NEW.total_deduction = NEW.share_deduction_total + NEW.cd_deduction_total;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table cd_share_deductions
-- ----------------------------
DROP TRIGGER IF EXISTS `cdshare_bankbalance`;
delimiter ;;
CREATE TRIGGER `cdshare_bankbalance` AFTER INSERT ON `cd_share_deductions` FOR EACH ROW BEGIN

    IF NEW.cd_deduction != 0 THEN
            amount,
            balance,
            bank_name,
            category,
            leasuretype,
            name,
            paymenttype,
            transaction_date,
            transaction_id,
            user_id
        ) VALUES (
            NEW.cd_deduction,
            (SELECT COALESCE(latest.balance, 0) + NEW.cd_deduction
             FROM (SELECT balance FROM bank_balance ORDER BY id DESC LIMIT 1) AS latest),
            (SELECT bank_name FROM banks WHERE user_id = NEW.user_id),
            'CD Deduction',
            1,
            (SELECT name FROM users WHERE user_id = NEW.user_id),
            0,
            NEW.payment_date,
            NEW.id,
            NEW.user_id
        );
    END IF;

    IF NEW.share_deduction != 0 THEN
            amount,
            balance,
            bank_name,
            category,
            leasuretype,
            name,
            paymenttype,
            transaction_date,
            transaction_id,
            user_id
        ) VALUES (
            NEW.share_deduction,
            (SELECT COALESCE(latest.balance, 0) + NEW.share_deduction
             FROM (SELECT balance FROM bank_balance ORDER BY id DESC LIMIT 1) AS latest),
            (SELECT bank_name FROM banks WHERE user_id = NEW.user_id),
            'Share Deduction',
            1,
            (SELECT name FROM users WHERE user_id = NEW.user_id),
            0,
            NEW.payment_date,
            NEW.id,
            NEW.user_id
        );
    END IF;

END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table emi_payments_details
-- ----------------------------
DROP TRIGGER IF EXISTS `before_emi_insert_copy1_copy1`;
delimiter ;;
CREATE TRIGGER `before_emi_insert_copy1_copy1` BEFORE INSERT ON `emi_payments_details` FOR EACH ROW BEGIN
    DECLARE v_loan_id BIGINT;
    DECLARE v_intrest_rate DECIMAL(10,2);
    DECLARE v_principal_remaing DECIMAL(10,2);
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_total_paid DECIMAL(10,2);

    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    
    SET v_loan_id = NULL;
    SET v_intrest_rate = 0;
    SET v_principal_remaing = 0;
    SET v_total_paid = 0;

    
    IF NEW.loan_id IS NULL THEN

        SET done = FALSE;

        
        SELECT id, intrest_rate, loan_repaid
        INTO v_loan_id, v_intrest_rate, v_total_paid
        FROM loans
        WHERE user_id = NEW.user_id
          AND loan_type = NEW.loan_type
          AND loan_status = 3
        ORDER BY id DESC
        LIMIT 1;
        
        SELECT principal_remaing 
        INTO v_principal_remaing
        FROM emi_payments_details WHERE 
			user_id=NEW.user_id AND 
			loan_type= NEW.loan_type 
		ORDER BY payment_date DESC 
		LIMIT 1;

        
        IF NOT done THEN
            SET NEW.loan_id = v_loan_id;
            SET NEW.intrest_rate = v_intrest_rate;
            SET NEW.emi_payment_type = 0;
            SET NEW.total_paid = v_total_paid + NEW.emi_amount;
        END IF;
    END IF;

    
    SET NEW.principal_remaing = v_principal_remaing - NEW.emi_amount;

END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table emi_payments_details
-- ----------------------------
DROP TRIGGER IF EXISTS `after_emi_insert_combined_copy1_copy1`;
delimiter ;;
CREATE TRIGGER `after_emi_insert_combined_copy1_copy1` AFTER INSERT ON `emi_payments_details` FOR EACH ROW BEGIN
    
    DECLARE txn_intst VARCHAR(100);
    DECLARE txn_emi VARCHAR(100);
    DECLARE bank_name_val VARCHAR(255);
    DECLARE user_name_val VARCHAR(255);
    DECLARE txn_name VARCHAR(100);
    DECLARE v_loan_id BIGINT;
    DECLARE v_generated_interest DOUBLE;
    DECLARE v_interest_diff DOUBLE;
    DECLARE v_existing_diff DOUBLE;
    DECLARE current_balance DOUBLE;
    
    
    SELECT id INTO v_loan_id
    FROM loans
    WHERE user_id = NEW.user_id
      AND loan_type = NEW.loan_type
    ORDER BY id DESC
    LIMIT 1;

    
    
    
    UPDATE loans
    SET loan_balance = loan_balance - NEW.emi_amount
    WHERE id = v_loan_id
      AND user_id = NEW.user_id
      AND loan_type = NEW.loan_type;

    
    
    
    

    
    
    
    
    
    SELECT interest INTO v_generated_interest
    FROM interest_on_loan
    WHERE loan_id = NEW.loan_id
      AND user_id = NEW.user_id
      AND YEAR(generated_for) = YEAR(NEW.payment_date)
      AND MONTH(generated_for) = MONTH(NEW.payment_date)
      AND NEW.emi_payment_type = 0
    LIMIT 1;
    
    
    IF v_generated_interest IS NOT NULL THEN
        
        SET v_interest_diff = v_generated_interest - NEW.uploaded_interest;
        
        
        SELECT interest_diff INTO v_existing_diff
        FROM loans
        WHERE id = NEW.loan_id
        LIMIT 1;
        
        
        UPDATE loans
        SET interest_diff = IFNULL(v_existing_diff, 0) + v_interest_diff
        WHERE id = NEW.loan_id;
        
        
    END IF;

    
    
    
    
END
;;
delimiter ;

