-- ----------------------------
-- Triggers structure for table interest_on_loan
-- ----------------------------
DROP TRIGGER IF EXISTS `interest_after_report`;
delimiter ;;
CREATE TRIGGER `interest_after_report` AFTER INSERT ON `interest_on_loan` FOR EACH ROW BEGIN

	DECLARE user_share DOUBLE DEFAULT 0;
    DECLARE user_cd DOUBLE DEFAULT 0;
    DECLARE uname VARCHAR(100) DEFAULT '';

    SELECT share_cut, cd_cut, name
    INTO user_share, user_cd, uname
    FROM users
    WHERE user_id = NEW.user_id
    LIMIT 1;

        
        user_id,
        share_upload,
        cd_upload,
        normal_balance_generated,
        noraml_recovery_generated,
        normal_interest_generated,
        comm_balance_generated,
        comm_recovery_generated,
        comm_interest_generated,
        created_for,
        created_at,
        company_id,
        name
    )
    VALUES (
        
        NEW.user_id,
		user_share,
        user_cd,
        CASE WHEN NEW.loan_type = 0 THEN NEW.loan_balance ELSE 0 END,
        CASE WHEN NEW.loan_type = 0 THEN NEW.instalment ELSE 0 END,
        CASE WHEN NEW.loan_type = 0 THEN NEW.interest ELSE 0 END,
        CASE WHEN NEW.loan_type = 1 THEN NEW.loan_balance ELSE 0 END,
        CASE WHEN NEW.loan_type = 1 THEN NEW.instalment ELSE 0 END,
        CASE WHEN NEW.loan_type = 1 THEN NEW.interest ELSE 0 END,
        NEW.generated_for,
        NEW.created_at,
        NEW.company_id,
        uname
    );

END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table interest_on_loan
-- ----------------------------
DROP TRIGGER IF EXISTS `after_interest_on_loan_update`;
delimiter ;;
CREATE TRIGGER `after_interest_on_loan_update` AFTER UPDATE ON `interest_on_loan` FOR EACH ROW BEGIN
    DECLARE user_share DOUBLE DEFAULT 0;
    DECLARE user_cd DOUBLE DEFAULT 0;
    DECLARE uname VARCHAR(100) DEFAULT '';

    SELECT share_cut, cd_cut, name
    INTO user_share, user_cd, uname
    FROM users
    WHERE user_id = NEW.user_id
    LIMIT 1;

    UPDATE report_data
    SET 
        share_upload = user_share,
        cd_upload = user_cd,
        normal_balance_generated = CASE WHEN NEW.loan_type = 0 THEN NEW.loan_balance ELSE normal_balance_generated END,
        noraml_recovery_generated = CASE WHEN NEW.loan_type = 0 THEN NEW.instalment ELSE noraml_recovery_generated END,
        normal_interest_generated = CASE WHEN NEW.loan_type = 0 THEN NEW.interest ELSE normal_interest_generated END,
        comm_balance_generated = CASE WHEN NEW.loan_type = 1 THEN NEW.loan_balance ELSE comm_balance_generated END,
        comm_recovery_generated = CASE WHEN NEW.loan_type = 1 THEN NEW.instalment ELSE comm_recovery_generated END,
        comm_interest_generated = CASE WHEN NEW.loan_type = 1 THEN NEW.interest ELSE comm_interest_generated END,
        created_for = NEW.generated_for,
        created_at = NEW.created_at,
        company_id=NEW.company_id,
        name=uname
    WHERE user_id = NEW.user_id
    AND created_for = NEW.generated_for;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table interest_on_loan
-- ----------------------------
DROP TRIGGER IF EXISTS `delete_report_data`;
delimiter ;;
CREATE TRIGGER `delete_report_data` AFTER DELETE ON `interest_on_loan` FOR EACH ROW BEGIN
    DELETE FROM report_data
    WHERE user_id = OLD.user_id
      AND created_for = OLD.generated_for
      AND company_id=OLD.company_id;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
